import http.server as h, functools as f
class H(h.SimpleHTTPRequestHandler):
    def translate_path(self, path):
        prefix = '/tbaguette-skills'
        return super().translate_path(path[len(prefix):] if path.startswith(prefix) else path)
h.ThreadingHTTPServer(('127.0.0.1', 8844), f.partial(H, directory='docs')).serve_forever()
